-- Generated by model/lib/sql/generate.mjs. The data's own members of each dimension, from dimensions/<Dimension>.csv in the folder of input cells,
-- numbered after the model's members. Parents first, so a member's parent ids exist when it goes in.

-- Brand Group
INSERT INTO "dim Brand Group" SELECT (SELECT coalesce(max("Brand Group"), 0) FROM "dim Brand Group") + row_number() OVER (ORDER BY c."Brand Group"), c."Brand Group"
FROM read_csv('dimensions/Brand Group.csv', header = true, all_varchar = true) c 
WHERE c."Brand Group" NOT IN (SELECT name FROM "dim Brand Group");

-- Brand
INSERT INTO "dim Brand" SELECT (SELECT coalesce(max("Brand"), 0) FROM "dim Brand") + row_number() OVER (ORDER BY c."Brand"), c."Brand", coalesce(p0."Brand Group", error('Brand ' || c."Brand" || ' has a Brand Group the dimension does not have: ' || c."Brand Group")), coalesce(p1."Brand Type", error('Brand ' || c."Brand" || ' has a Brand Type the dimension does not have: ' || c."Brand Type"))
FROM read_csv('dimensions/Brand.csv', header = true, all_varchar = true) c LEFT JOIN "dim Brand Group" p0 ON p0.name = coalesce(nullif(c."Brand Group", ''), 'NULL (Brand Group)') LEFT JOIN "dim Brand Type" p1 ON p1.name = coalesce(nullif(c."Brand Type", ''), 'NULL (Brand Type)')
WHERE c."Brand" NOT IN (SELECT name FROM "dim Brand");

